53	const PROCESSING_FEE = 5;
54	const FIRST_INSURANCE_SURCHARGE_RATE = 0.1;
55	const CURSE_SURCHARGE_RATE = 0.5;
56	const HIGH_ENCHANTMENT_THRESHOLD = 5;
57	const HIGH_ENCHANTMENT_SURCHARGE_RATE = 0.3;
58	const LOYALTY_YEARS_THRESHOLD = 2;
59	const LOYALTY_DISCOUNT_RATE = 0.2;
60	const BASE_PREMIUMS: Record<string, number> = {
61	  sword: 100,
62	  amulet: 60,
63	  staff: 80,
64	  potion: 40,
65	  rune: 25,
66	  moonstone: 25,
67	};
68	
69	const BLOCK_SIZE = 3;
70	const COMPONENT_BLOCK_PREMIUM = 60;
71	
72	const COMPONENT_TYPES = ["rune", "moonstone"];
73	
74	const componentBlockAdjustment = (
75	  items: Item[],
76	  componentType: string,
77	): number => {
78	  const count = items.filter((item) => item.type === componentType).length;
79	  return count === BLOCK_SIZE
80	    ? COMPONENT_BLOCK_PREMIUM - BLOCK_SIZE * BASE_PREMIUMS[componentType]
81	    : 0;
82	};
83	
84	const basePremiumFor = (items: Item[]): number =>
85	  items.reduce((total, item) => total + BASE_PREMIUMS[item.type], 0) +
86	  COMPONENT_TYPES.reduce(
87	    (total, componentType) => total + componentBlockAdjustment(items, componentType),
88	    0,
89	  );
90	
91	const surchargeFor = (
92	  items: Item[],
93	  rate: number,
94	  applies: (item: Item) => boolean,
95	): number =>
96	  items.reduce(
97	    (total, item) =>
98	      total + (applies(item) ? rate * BASE_PREMIUMS[item.type] : 0),
99	    0,
100	  );
101	
102	const isCursed = (item: Item): boolean => item.cursed === true;
103	
104	const isHighlyEnchanted = (item: Item): boolean =>
105	  (item.enchantment ?? 0) >= HIGH_ENCHANTMENT_THRESHOLD;
106	
107	const curseSurchargeFor = (items: Item[]): number =>
108	  surchargeFor(items, CURSE_SURCHARGE_RATE, isCursed);
109	
110	const highEnchantmentSurchargeFor = (items: Item[]): number =>
111	  surchargeFor(items, HIGH_ENCHANTMENT_SURCHARGE_RATE, isHighlyEnchanted);
112	
113	const quotePremium = (
114	  basePremium: number,
115	  itemSurcharges: number,
116	  customer: Customer,
117	  isFollowUpContract: boolean,
118	): number => {
119	  const firstInsuranceSurcharge = basePremium * FIRST_INSURANCE_SURCHARGE_RATE;
120	  const loyaltyDiscount =
121	    customer.yearsWithMHPCO >= LOYALTY_YEARS_THRESHOLD
122	      ? basePremium * LOYALTY_DISCOUNT_RATE
123	      : 0;
124	  const followUpDiscount = isFollowUpContract ? basePremium * 0.15 : 0;
125	  return Math.ceil(
126	    basePremium +
127	      itemSurcharges +
128	      firstInsuranceSurcharge -
129	      loyaltyDiscount -
130	      followUpDiscount +
131	      PROCESSING_FEE,
132	  );
133	};
