135	export const runScenario = (scenario: Scenario): ScenarioOutput => {
136	  const results = scenario.steps.map((step, index) => {
137	    const quoteStep = step as QuoteStep;
138	    const premium = quotePremium(
139	      basePremiumFor(quoteStep.items),
140	      curseSurchargeFor(quoteStep.items) +
141	        highEnchantmentSurchargeFor(quoteStep.items),
142	      scenario.customer,
143	      index > 0,
144	    );
145	    return { premium };
146	  });
147	  return { results };
148	};
